CornerStrategySpec: TypeAlias = Literal["chess", "radon"]
"""The corner detector a chessboard-like detector runs. The manifest's copy
of the detector's corner strategy (see `DetectorSpec`).

- ``"chess"``: The ChESS response. Fast; the default.
- ``"radon"``: The whole-image Radon response. Several times slower than ChESS, and
  less biased at a corner's sub-pixel position on sharp, finely sampled
  boards (e.g. rendered ones).
"""


class _CorrespondenceViewRequired(TypedDict):
    """The keys of `CorrespondenceView` that every payload has."""

    points_2d: list[tuple[float, float] | list[float]]
    """The matching image points `[u, v]`, pixels."""

    points_3d: list[tuple[float, float, float] | list[float]]
    """3D points `[x, y, z]` in the target frame, metres."""


class CorrespondenceView(_CorrespondenceViewRequired, total=False):
    """A single view containing 2D-3D point correspondences.

    This is the canonical observation type used across planar intrinsics,
    rig extrinsics, hand-eye calibration, and other calibration problems.

    # Fields

    - `points_3d`: 3D points in world/target coordinates
    - `points_2d`: Corresponding 2D pixel observations
    - `cov_px`: optionally, the covariance of each image point
      (`PointCovariance`, px²)
    - `blur`: optionally, the blur measured at each image point
      (`PointBlur`), `None` for a point without one

    Within one calibration input either every view carries covariances or
    none does. The blur is a measurement carried with the points: any point
    may have one or not, and no calibration reads it.

    # Example

    ```
    use vision_calibration_core::{CorrespondenceView, PointCovariance, Pt2, Pt3};

    let points_3d = vec![Pt3::new(0.0, 0.0, 0.0), Pt3::new(0.1, 0.0, 0.0)];
    let points_2d = vec![Pt2::new(320.0, 240.0), Pt2::new(400.0, 240.0)];
    let view = CorrespondenceView::new(points_3d.clone(), points_2d.clone()).unwrap();
    assert_eq!(view.len(), 2);
    assert!(view.covariances().is_none());

    // With a stated covariance per point.
    let cov = PointCovariance::new(0.04, 0.0, 0.04).unwrap();
    let view =
        CorrespondenceView::new_with_covariances(points_3d, points_2d, vec![cov; 2]).unwrap();
    assert_eq!(view.covariance(1), Some(cov));
    ```
    """

    blur: list[PointBlur | None]
    """The blur measured at each image point, one per point, `null` for a
    point without one; absent or empty when no point has one.
    """

    cov_px: list[PointCovariance]
    """The covariance of each image point, px², one per point; absent or
    empty when not stated. Within one calibration input either every
    view states them or none does.
    """


class CrossValidationOptions(TypedDict, total=False):
    """How `compare_camera_models` splits the views into folds.

    The views are shuffled by a seeded generator whose sequence is fixed by
    this library, not by a dependency, so a seed gives the same folds on
    every platform and release; the `i`-th shuffled view goes to fold
    `i mod folds`, so fold sizes differ by at most one.
    """

    folds: int
    """Number of folds `K`, at least 2 and at most the number of views
    (`K` equal to the number of views is leave-one-view-out). Each fit
    sees about `(K − 1)/K` of the views and must keep at least three.
    Default 5: each fit keeps 80 % of the views, and five fits per
    candidate keep the cost moderate.
    """

    seed: int
    """Seed of the shuffle that assigns views to folds, any value. Default
    0. Another seed gives another partition; a ranking that changes with
    the seed is not a reliable one.
    """


